      "code": "class Solution {\npublic:\n    bool isHappy(int n) {\n        unordered_set<int> vis;\n        while (n != 1 && !vis.count(n)) {\n            vis.insert(n);\n            int x = 0;\n            for (; n; n /= 10) {\n                x += (n % 10) * (n % 10);\n            }\n            n = x;\n        }\n        return n == 1;\n    }\n};"
