      "code": "class Solution {\npublic:\n    bool isHappy(int n) {\n        auto next = [](int x) {\n            int y = 0;\n            for (; x; x /= 10) {\n                y += pow(x % 10, 2);\n            }\n            return y;\n        };\n        int slow = n, fast = next(n);\n        while (slow != fast) {\n            slow = next(slow);\n            fast = next(next(fast));\n        }\n        return slow == 1;\n    }\n};"
