      "code": "class Solution {\npublic:\n    vector<vector<int>> combine(int n, int k) {\n        vector<vector<int>> ans;\n        vector<int> t;\n        function<void(int)> dfs = [&](int i) {\n            if (t.size() == k) {\n                ans.emplace_back(t);\n                return;\n            }\n            if (i > n) {\n                return;\n            }\n            for (int j = i; j <= n; ++j) {\n                t.emplace_back(j);\n                dfs(j + 1);\n                t.pop_back();\n            }\n        };\n        dfs(1);\n        return ans;\n    }\n};"
