      "code": "class Solution {\npublic:\n    int findMaxForm(vector<string>& strs, int m, int n) {\n        int f[m + 1][n + 1];\n        memset(f, 0, sizeof(f));\n        for (auto& s : strs) {\n            auto [a, b] = count(s);\n            for (int i = m; i >= a; --i) {\n                for (int j = n; j >= b; --j) {\n                    f[i][j] = max(f[i][j], f[i - a][j - b] + 1);\n                }\n            }\n        }\n        return f[m][n];\n    }\n\n    pair<int, int> count(string& s) {\n        int a = count_if(s.begin(), s.end(), [](char c) { return c == '0'; });\n        return {a, s.size() - a};\n    }\n};"
