      "code": "class Solution {\npublic:\n    int minSwaps(string s) {\n        int x = 0;\n        for (char& c : s) {\n            if (c == '[') {\n                ++x;\n            } else if (x) {\n                --x;\n            }\n        }\n        return (x + 1) / 2;\n    }\n};"
