  "lfu-cache": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Space $O(n)$，其中 $n$ 为缓存的容量",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 0460.LFU Cache Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/0400-0499/0460.LFU%20Cache/README.md",
      "code": "class Node {\npublic:\n    int key;\n    int value;\n    int freq;\n    Node* prev;\n    Node* next;\n    Node(int key, int value) {\n        this->key = key;\n        this->value = value;\n        this->freq = 1;\n        this->prev = nullptr;\n        this->next = nullptr;\n    }\n};\n\nclass DoublyLinkedList {\npublic:\n    Node* head;\n    Node* tail;\n    DoublyLinkedList() {\n        this->head = new Node(-1, -1);\n        this->tail = new Node(-1, -1);\n        this->head->next = this->tail;\n        this->tail->prev = this->head;\n    }\n    void addFirst(Node* node) {\n        node->prev = this->head;\n        node->next = this->head->next;\n        this->head->next->prev = node;\n        this->head->next = node;\n    }\n    Node* remove(Node* node) {\n        node->next->prev = node->prev;\n        node->prev->next = node->next;\n        node->next = nullptr;\n        node->prev = nullptr;\n        return node;\n    }\n    Node* removeLast() {\n        return remove(this->tail->prev);\n    }\n    bool isEmpty() {\n        return this->head->next == this->tail;\n    }\n};\n\nclass LFUCache {\npublic:\n    LFUCache(int capacity) {\n        this->capacity = capacity;\n        this->minFreq = 0;\n    }\n\n    int get(int key) {\n        if (capacity == 0 || map.find(key) == map.end()) {\n            return -1;\n        }\n        Node* node = map[key];\n        incrFreq(node);\n        return node->value;\n    }\n\n    void put(int key, int value) {\n        if (capacity == 0) {\n            return;\n        }\n        if (map.find(key) != map.end()) {\n            Node* node = map[key];\n            node->value = value;\n            incrFreq(node);\n            return;\n        }\n        if (map.size() == capacity) {\n            DoublyLinkedList* list = freqMap[minFreq];\n            Node* node = list->removeLast();\n            map.erase(node->key);\n        }\n        Node* node = new Node(key, value);\n        addNode(node);\n        map[key] = node;\n        minFreq = 1;\n    }\n\nprivate:\n    int capacity;\n    int minFreq;\n    unordered_map<int, Node*> map;\n    unordered_map<int, DoublyLinkedList*> freqMap;\n\n    void incrFreq(Node* node) {\n        int freq = node->freq;\n        DoublyLinkedList* list = freqMap[freq];\n        list->remove(node);\n        if (list->isEmpty()) {\n            freqMap.erase(freq);\n            if (freq == minFreq) {\n                minFreq++;\n            }\n        }\n        node->freq++;\n        addNode(node);\n    }\n\n    void addNode(Node* node) {\n        int freq = node->freq;\n        if (freqMap.find(freq) == freqMap.end()) {\n            freqMap[freq] = new DoublyLinkedList();\n        }\n        DoublyLinkedList* list = freqMap[freq];\n        list->addFirst(node);\n        freqMap[freq] = list;\n    }\n};\n\n/**\n * Your LFUCache object will be instantiated and called as such:\n * LFUCache* obj = new LFUCache(capacity);\n * int param_1 = obj->get(key);\n * obj->put(key,value);\n */"
    }
  ],
