  "sliding-puzzle": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 0773.Sliding Puzzle Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/0700-0799/0773.Sliding%20Puzzle/README.md",
      "code": "class Solution {\npublic:\n    int slidingPuzzle(vector<vector<int>>& board) {\n        string start = gets(board);\n        string end = \"123450\";\n        if (start == end) return 0;\n        unordered_set<string> vis;\n        vis.insert(start);\n        queue<string> q{{start}};\n        int ans = 0;\n        while (!q.empty()) {\n            ++ans;\n            for (int n = q.size(); n > 0; --n) {\n                string x = q.front();\n                q.pop();\n                setb(x, board);\n                for (string y : next(board)) {\n                    if (y == end) return ans;\n                    if (!vis.count(y)) {\n                        vis.insert(y);\n                        q.push(y);\n                    }\n                }\n            }\n        }\n        return -1;\n    }\n\n    string gets(vector<vector<int>>& board) {\n        string s = \"\";\n        for (int i = 0; i < 2; ++i)\n            for (int j = 0; j < 3; ++j)\n                s.push_back('0' + board[i][j]);\n        return s;\n    }\n\n    void setb(string s, vector<vector<int>>& board) {\n        for (int i = 0; i < 2; ++i)\n            for (int j = 0; j < 3; ++j)\n                board[i][j] = s[i * 3 + j] - '0';\n    }\n\n    vector<string> next(vector<vector<int>>& board) {\n        vector<string> res;\n        auto p = find0(board);\n        int i = p.first, j = p.second;\n        vector<int> dirs = {-1, 0, 1, 0, -1};\n        for (int k = 0; k < 4; ++k) {\n            int x = i + dirs[k], y = j + dirs[k + 1];\n            if (x >= 0 && x < 2 && y >= 0 && y < 3) {\n                swap(i, j, x, y, board);\n                res.push_back(gets(board));\n                swap(i, j, x, y, board);\n            }\n        }\n        return res;\n    }\n\n    void swap(int i, int j, int x, int y, vector<vector<int>>& board) {\n        int t = board[i][j];\n        board[i][j] = board[x][y];\n        board[x][y] = t;\n    }\n\n    pair<int, int> find0(vector<vector<int>>& board) {\n        for (int i = 0; i < 2; ++i)\n            for (int j = 0; j < 3; ++j)\n                if (board[i][j] == 0)\n                    return {i, j};\n        return {0, 0};\n    }\n};"
    },
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Solution 2",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 0773.Sliding Puzzle Solution 2",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/0700-0799/0773.Sliding%20Puzzle/README_EN.md",
      "code": "class Solution {\npublic:\n    int m = 2;\n    int n = 3;\n\n    int slidingPuzzle(vector<vector<int>>& board) {\n        string start, seq;\n        string end = \"123450\";\n        for (int i = 0; i < m; ++i) {\n            for (int j = 0; j < n; ++j) {\n                start += char(board[i][j] + '0');\n                if (board[i][j] != 0) seq += char(board[i][j] + '0');\n            }\n        }\n        if (!check(seq)) return -1;\n        typedef pair<int, string> PIS;\n        priority_queue<PIS, vector<PIS>, greater<PIS>> q;\n        unordered_map<string, int> dist;\n        dist[start] = 0;\n        q.push({f(start), start});\n        vector<int> dirs = {-1, 0, 1, 0, -1};\n        while (!q.empty()) {\n            PIS t = q.top();\n            q.pop();\n            string state = t.second;\n            int step = dist[state];\n            if (state == end) return step;\n            int p1 = state.find('0');\n            int i = p1 / n, j = p1 % n;\n            for (int k = 0; k < 4; ++k) {\n                int x = i + dirs[k], y = j + dirs[k + 1];\n                if (x < 0 || x >= m || y < 0 || y >= n) continue;\n                int p2 = x * n + y;\n                swap(state[p1], state[p2]);\n                if (!dist.count(state) || dist[state] > step + 1) {\n                    dist[state] = step + 1;\n                    q.push({step + 1 + f(state), state});\n                }\n                swap(state[p1], state[p2]);\n            }\n        }\n        return -1;\n    }\n\n    bool check(string s) {\n        int n = s.size();\n        int cnt = 0;\n        for (int i = 0; i < n; ++i)\n            for (int j = i; j < n; ++j)\n                if (s[i] > s[j])\n                    ++cnt;\n        return cnt % 2 == 0;\n    }\n\n    int f(string s) {\n        int ans = 0;\n        for (int i = 0; i < m * n; ++i) {\n            if (s[i] == '0') continue;\n            int num = s[i] - '1';\n            ans += abs(num / n - i / n) + abs(num % n - i % n);\n        }\n        return ans;\n    }\n};"
    }
  ],
