      "code": "class Solution {\npublic:\n    bool isUnique(string astr) {\n        int mask = 0;\n        for (char c : astr) {\n            int i = c - 'a';\n            if (mask >> i & 1) {\n                return false;\n            }\n            mask |= 1 << i;\n        }\n        return true;\n    }\n};"
