  "design-twitter": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/design-twitter.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/design-twitter.cpp",
      "code": "// Time:  O(u + klogk), k is most recently number of tweets,\n//                      u is the number of the user's following.\n// Space: O(t + f), t is the total number of tweets,\n//                  f is the total number of followings.\n\nclass Twitter {\npublic:\n    /** Initialize your data structure here. */\n    Twitter() : time_(0) {\n        \n    }\n    \n    /** Compose a new tweet. */\n    void postTweet(int userId, int tweetId) {\n        messages_[userId].emplace_back(make_pair(++time_, tweetId));\n    }\n    \n    /** Retrieve the 10 most recent tweet ids in the user's news feed. Each item in the news feed must be posted by users who the user followed or by the user herself. Tweets must be ordered from most recent to least recent. */\n    vector<int> getNewsFeed(int userId) {\n        using RIT = deque<pair<size_t, int>>::reverse_iterator;\n\n        vector<tuple<size_t, RIT, RIT>> candidates;\n        if (messages_[userId].size()) {\n            candidates.emplace_back(messages_[userId].rbegin()->first,\n                                    messages_[userId].rbegin(),\n                                    messages_[userId].rend());\n        }\n        for (const auto& id : followings_[userId]) {\n            if (messages_[id].size()) {\n                candidates.emplace_back(messages_[id].rbegin()->first,\n                                        messages_[id].rbegin(),\n                                        messages_[id].rend());\n            }\n        }\n        if (size(candidates) > number_of_most_recent_tweets_) {\n            nth_element(begin(candidates), begin(candidates) + number_of_most_recent_tweets_ - 1, end(candidates));\n        }\n        priority_queue<tuple<size_t, RIT, RIT>> heap(cbegin(candidates), cbegin(candidates) + min(size(candidates), number_of_most_recent_tweets_));\n        vector<int> res;\n        while (!heap.empty() && res.size() < number_of_most_recent_tweets_) {\n            const auto& top = heap.top();\n            size_t t;\n            RIT begin, end;\n            tie(t, begin, end) = top;\n            heap.pop();\n\n            auto next = begin + 1;\n            if (next != end) {\n                heap.emplace(make_tuple(next->first, next, end));\n            }\n\n            res.emplace_back(begin->second);\n        }\n        return res;\n    }\n    \n    /** Follower follows a followee. If the operation is invalid, it should be a no-op. */\n    void follow(int followerId, int followeeId) {\n        if (followerId != followeeId && !followings_[followerId].count(followeeId)) {\n            followings_[followerId].emplace(followeeId);\n        }\n    }\n    \n    /** Follower unfollows a followee. If the operation is invalid, it should be a no-op. */\n    void unfollow(int followerId, int followeeId) {\n        if (followings_[followerId].count(followeeId)) {\n            followings_[followerId].erase(followeeId);\n        }\n    }\n\nprivate:\n    const size_t number_of_most_recent_tweets_ = 10;\n    unordered_map<int, unordered_set<int>> followings_;\n    unordered_map<int, deque<pair<size_t, int>>> messages_;\n    size_t time_;\n};"
    }
  ],
