      "code": "class Solution {\npublic:\n    bool isStraight(vector<int>& nums) {\n        bool vis[14]{};\n        int mi = 20, mx = -1;\n        for (int& x : nums) {\n            if (x == 0) {\n                continue;\n            }\n            if (vis[x]) {\n                return false;\n            }\n            vis[x] = true;\n            mi = min(mi, x);\n            mx = max(mx, x);\n        }\n        return mx - mi <= 4;\n    }\n};"
