  "bricks-falling-when-hit": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 0803.Bricks Falling When Hit Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/0800-0899/0803.Bricks%20Falling%20When%20Hit/README.md",
      "code": "class Solution {\npublic:\n    vector<int> p;\n    vector<int> size;\n\n    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {\n        int m = grid.size(), n = grid[0].size();\n        p.resize(m * n + 1);\n        size.resize(m * n + 1);\n        for (int i = 0; i < p.size(); ++i) {\n            p[i] = i;\n            size[i] = 1;\n        }\n        vector<vector<int>> g(m, vector<int>(n));\n        for (int i = 0; i < m; ++i)\n            for (int j = 0; j < n; ++j)\n                g[i][j] = grid[i][j];\n        for (auto& h : hits) g[h[0]][h[1]] = 0;\n        for (int j = 0; j < n; ++j)\n            if (g[0][j] == 1)\n                merge(j, m * n);\n        for (int i = 1; i < m; ++i) {\n            for (int j = 0; j < n; ++j) {\n                if (g[i][j] == 0) continue;\n                if (g[i - 1][j] == 1) merge(i * n + j, (i - 1) * n + j);\n                if (j > 0 && g[i][j - 1] == 1) merge(i * n + j, i * n + j - 1);\n            }\n        }\n        vector<int> ans(hits.size());\n        vector<int> dirs = {-1, 0, 1, 0, -1};\n        for (int k = hits.size() - 1; k >= 0; --k) {\n            int i = hits[k][0], j = hits[k][1];\n            if (grid[i][j] == 0) continue;\n            g[i][j] = 1;\n            int prev = size[find(m * n)];\n            if (i == 0) merge(j, m * n);\n            for (int l = 0; l < 4; ++l) {\n                int x = i + dirs[l], y = j + dirs[l + 1];\n                if (x >= 0 && x < m && y >= 0 && y < n && g[x][y] == 1)\n                    merge(i * n + j, x * n + y);\n            }\n            int curr = size[find(m * n)];\n            ans[k] = max(0, curr - prev - 1);\n        }\n        return ans;\n    }\n\n    int find(int x) {\n        if (p[x] != x) p[x] = find(p[x]);\n        return p[x];\n    }\n\n    void merge(int a, int b) {\n        int pa = find(a), pb = find(b);\n        if (pa != pb) {\n            size[pb] += size[pa];\n            p[pa] = pb;\n        }\n    }\n};"
    }
  ],
  "minimum-cost-to-hire-k-workers": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n\\log n)$，空间复杂度 $O(n)$ / Space $O(n)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 0857.Minimum Cost to Hire K Workers Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/0800-0899/0857.Minimum%20Cost%20to%20Hire%20K%20Workers/README.md",
      "code": "class Solution {\npublic:\n    double mincostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {\n        int n = quality.size();\n        vector<pair<double, int>> t(n);\n        for (int i = 0; i < n; ++i) {\n            t[i] = {(double) wage[i] / quality[i], quality[i]};\n        }\n        sort(t.begin(), t.end());\n        priority_queue<int> pq;\n        double ans = 1e18;\n        int tot = 0;\n        for (auto& [x, q] : t) {\n            tot += q;\n            pq.push(q);\n            if (pq.size() == k) {\n                ans = min(ans, tot * x);\n                tot -= pq.top();\n                pq.pop();\n            }\n        }\n        return ans;\n    }\n};"
    }
  ],
