      "code": "class Solution {\npublic:\n    int maxDepth(string s) {\n        int ans = 0, d = 0;\n        for (char& c : s) {\n            if (c == '(') {\n                ans = max(ans, ++d);\n            } else if (c == ')') {\n                --d;\n            }\n        }\n        return ans;\n    }\n};"
