  "reverse-nodes-in-even-length-groups": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/reverse-nodes-in-even-length-groups.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/reverse-nodes-in-even-length-groups.cpp",
      "code": "// Time:  O(n)\n// Space: O(1)\n\nclass Solution {\npublic:\n    ListNode* reverseEvenLengthGroups(ListNode* head) {\n        auto prev = head;\n        int l = 2;\n        while (prev->next) {\n            auto curr = prev;\n            int cnt = 0;\n            for (; cnt < l && curr->next; ++cnt, curr = curr->next);\n            ++l;\n            if (cnt % 2) {\n                prev = curr;\n                continue;\n            }\n            curr = prev->next;\n            ListNode *last = nullptr;\n            while (cnt--) {\n                auto nxt = curr->next;\n                curr->next = last;\n                last = curr;\n                curr = nxt;\n            }\n            auto tail = prev->next;\n            tail->next = curr;\n            prev->next = last;\n            prev = tail;\n        }\n        return head;\n    }\n};"
    }
  ],
