      "code": "class Solution {\npublic:\n    vector<int> findKDistantIndices(vector<int>& nums, int key, int k) {\n        vector<int> idx;\n        int n = nums.size();\n        for (int i = 0; i < n; ++i) {\n            if (nums[i] == key) {\n                idx.push_back(i);\n            }\n        }\n        vector<int> ans;\n        for (int i = 0; i < n; ++i) {\n            auto it1 = lower_bound(idx.begin(), idx.end(), i - k);\n            auto it2 = upper_bound(idx.begin(), idx.end(), i + k) - 1;\n            if (it1 <= it2) {\n                ans.push_back(i);\n            }\n        }\n        return ans;\n    }\n};"
