      "code": "class Solution {\npublic:\n    bool queryString(string s, int n) {\n        if (n > 1000) {\n            return false;\n        }\n        for (int i = n; i > n / 2; --i) {\n            string b = bitset<32>(i).to_string();\n            b = b.substr(b.find_first_not_of('0'));\n            if (s.find(b) == string::npos) {\n                return false;\n            }\n        }\n        return true;\n    }\n};"
