  "number-of-ways-to-paint-sheets": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/number-of-ways-to-paint-sheets.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/number-of-ways-to-paint-sheets.cpp",
      "code": "// Time:  O(mlogm)\n// Space: O(m)\n\n// sort, prefix sum, two pointers\nclass Solution {\npublic:\n    int numberOfWays(int n, vector<int>& limit) {\n        static const int MOD = 1e9 + 7;\n\n        ranges::sort(limit);\n        vector<int64_t> suffix(size(limit) + 1);        \n        for(int i = size(limit) - 1; i >= 0; i--) {\n            limit[i] = min(limit[i], n - 1);\n            suffix[i] = suffix[i + 1] + limit[i];\n        }\n        int64_t result = 0;\n        for (int i = size(limit) - 1, j = 0; i >= 0; --i) {\n            for (; j < size(limit); ++j) {\n                if (limit[i] + limit[j] >= n) {\n                    break;\n                }\n            }\n            int64_t cnt = (limit[i] - n + 1) * (size(limit) - j)  + suffix[j];\n            if (i >= j) {\n                cnt -= limit[i] + limit[i] - n + 1;\n            }\n            result = (result + cnt) % MOD;\n        }\n        return result;\n    }\n};"
    }
  ],
