      "code": "class Solution {\npublic:\n    bool checkZeroOnes(string s) {\n        auto f = [&](char x) {\n            int cnt = 0, mx = 0;\n            for (char& c : s) {\n                if (c == x) {\n                    mx = max(mx, ++cnt);\n                } else {\n                    cnt = 0;\n                }\n            }\n            return mx;\n        };\n        return f('1') > f('0');\n    }\n};"
