      "code": "class Solution {\npublic:\n    int minimumK(vector<int>& nums) {\n        auto check = [&](int k) -> bool {\n            long long t = 0;\n            for (int x : nums) {\n                t += (x + k - 1) / k;\n            }\n            return t <= 1LL * k * k;\n        };\n\n        int l = 1, r = 1e5;\n        while (l < r) {\n            int mid = (l + r) >> 1;\n            if (check(mid)) {\n                r = mid;\n            } else {\n                l = mid + 1;\n            }\n        }\n        return l;\n    }\n};"
