  "once-twice": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/once-twice.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/once-twice.cpp",
      "code": "// Time:  O(n)\n// Space: O(1)\n\n// dp, bitmasks\nclass Solution {\npublic:\n    vector<int> onceTwice(vector<int>& nums) {\n        vector<int> dp(3), new_dp(3);\n        dp[0] = ~0;\n        for (const auto& x : nums) {\n            for (int i = 0; i < 3; ++i) {\n                new_dp[i] = (x & dp[i - 1 >= 0 ? i - 1 : 2]) | (~x & dp[i]);\n            }\n            swap(dp, new_dp);\n        }\n        vector<int> dp2(3), new_dp2(3);\n        dp2[0] = ~0;\n        for (const auto& x : nums) {\n            if ((~x & dp[1]) || (x & dp[2])) {\n                continue;\n            }\n            for (int i = 0; i < 3; ++i) {\n                new_dp2[i] = (x & dp2[i - 1 >= 0 ? i - 1 : 2]) | (~x & dp2[i]);\n            }\n            swap(dp2, new_dp2);\n        }\n        return {dp2[1], (dp2[1] ^ dp[1]) | dp[2]};\n    }\n};"
    }
  ],
  "maximum-hamming-distances": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(2^m)$，空间复杂度 $O(2^m)$ / Space $O(2^m)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3141.Maximum Hamming Distances Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3100-3199/3141.Maximum%20Hamming%20Distances/README.md",
      "code": "class Solution {\npublic:\n    vector<int> maxHammingDistances(vector<int>& nums, int m) {\n        int dist[1 << m];\n        memset(dist, -1, sizeof(dist));\n        queue<int> q;\n        for (int x : nums) {\n            dist[x] = 0;\n            q.push(x);\n        }\n        for (int k = 1; q.size(); ++k) {\n            for (int t = q.size(); t; --t) {\n                int x = q.front();\n                q.pop();\n                for (int i = 0; i < m; ++i) {\n                    int y = x ^ (1 << i);\n                    if (dist[y] == -1) {\n                        dist[y] = k;\n                        q.push(y);\n                    }\n                }\n            }\n        }\n        for (int& x : nums) {\n            x = m - dist[x ^ ((1 << m) - 1)];\n        }\n        return nums;\n    }\n};"
    }
  ],
