      "code": "class Solution {\npublic:\n    bool validTree(int n, vector<vector<int>>& edges) {\n        vector<int> p(n);\n        iota(p.begin(), p.end(), 0);\n        function<int(int)> find = [&](int x) {\n            if (p[x] != x) {\n                p[x] = find(p[x]);\n            }\n            return p[x];\n        };\n        for (auto& e : edges) {\n            int pa = find(e[0]), pb = find(e[1]);\n            if (pa == pb) {\n                return false;\n            }\n            p[pa] = pb;\n            --n;\n        }\n        return n == 1;\n    }\n};"
