      "code": "class Solution {\npublic:\n    int countComponents(int n, vector<vector<int>>& edges) {\n        vector<int> g[n];\n        for (auto& e : edges) {\n            int a = e[0], b = e[1];\n            g[a].push_back(b);\n            g[b].push_back(a);\n        }\n        vector<bool> vis(n);\n        int ans = 0;\n        for (int i = 0; i < n; ++i) {\n            if (vis[i]) {\n                continue;\n            }\n            vis[i] = true;\n            ++ans;\n            queue<int> q{{i}};\n            while (!q.empty()) {\n                int a = q.front();\n                q.pop();\n                for (int b : g[a]) {\n                    if (!vis[b]) {\n                        vis[b] = true;\n                        q.push(b);\n                    }\n                }\n            }\n        }\n        return ans;\n    }\n};"
