  "number-of-restricted-paths-from-first-to-last-node": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 1786.Number of Restricted Paths From First to Last Node Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/1700-1799/1786.Number%20of%20Restricted%20Paths%20From%20First%20to%20Last%20Node/README.md",
      "code": "using pii = pair<int, int>;\n\nclass Solution {\npublic:\n    const int inf = INT_MAX;\n    const int mod = 1e9 + 7;\n    vector<vector<pii>> g;\n    vector<int> dist;\n    vector<int> f;\n    int n;\n\n    int countRestrictedPaths(int n, vector<vector<int>>& edges) {\n        this->n = n;\n        g.resize(n + 1);\n        dist.assign(n + 1, inf);\n        f.assign(n + 1, -1);\n        dist[n] = 0;\n        for (auto& e : edges) {\n            int u = e[0], v = e[1], w = e[2];\n            g[u].emplace_back(v, w);\n            g[v].emplace_back(u, w);\n        }\n        priority_queue<pii, vector<pii>, greater<pii>> q;\n        q.emplace(0, n);\n        while (!q.empty()) {\n            auto [_, u] = q.top();\n            q.pop();\n            for (auto [v, w] : g[u]) {\n                if (dist[v] > dist[u] + w) {\n                    dist[v] = dist[u] + w;\n                    q.emplace(dist[v], v);\n                }\n            }\n        }\n        return dfs(1);\n    }\n\n    int dfs(int i) {\n        if (f[i] != -1) return f[i];\n        if (i == n) return 1;\n        int ans = 0;\n        for (auto [j, _] : g[i]) {\n            if (dist[i] > dist[j]) {\n                ans = (ans + dfs(j)) % mod;\n            }\n        }\n        f[i] = ans;\n        return ans;\n    }\n};"
    }
  ],
  "find-edges-in-shortest-paths": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(m \\times \\log m)$，空间复杂度 $O(n + m)$，其中 $n$ 和 $m$ 分别为节点数和边数 / Space $O(n + m)$，其中 $n$ 和 $m$ 分别为节点数和边数",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3123.Find Edges in Shortest Paths Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3100-3199/3123.Find%20Edges%20in%20Shortest%20Paths/README.md",
      "code": "class Solution {\npublic:\n    vector<bool> findAnswer(int n, vector<vector<int>>& edges) {\n        vector<vector<array<int, 3>>> g(n);\n        int m = edges.size();\n        for (int i = 0; i < m; ++i) {\n            auto e = edges[i];\n            int a = e[0], b = e[1], w = e[2];\n            g[a].push_back({b, w, i});\n            g[b].push_back({a, w, i});\n        }\n        const int inf = 1 << 30;\n        vector<int> dist(n, inf);\n        dist[0] = 0;\n\n        using pii = pair<int, int>;\n        priority_queue<pii, vector<pii>, greater<pii>> pq;\n        pq.push({0, 0});\n\n        while (!pq.empty()) {\n            auto [da, a] = pq.top();\n            pq.pop();\n            if (da > dist[a]) {\n                continue;\n            }\n\n            for (auto [b, w, _] : g[a]) {\n                if (dist[b] > dist[a] + w) {\n                    dist[b] = dist[a] + w;\n                    pq.push({dist[b], b});\n                }\n            }\n        }\n        vector<bool> ans(m);\n        if (dist[n - 1] == inf) {\n            return ans;\n        }\n        queue<int> q{{n - 1}};\n        while (!q.empty()) {\n            int a = q.front();\n            q.pop();\n            for (auto [b, w, i] : g[a]) {\n                if (dist[a] == dist[b] + w) {\n                    ans[i] = true;\n                    q.push(b);\n                }\n            }\n        }\n        return ans;\n    }\n};"
    }
  ],
  "number-of-ways-to-arrive-at-destination": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n^2)$，空间复杂度 $O(n^2)$ / Space $O(n^2)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 1976.Number of Ways to Arrive at Destination Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/1900-1999/1976.Number%20of%20Ways%20to%20Arrive%20at%20Destination/README.md",
      "code": "class Solution {\npublic:\n    int countPaths(int n, vector<vector<int>>& roads) {\n        const long long inf = LLONG_MAX / 2;\n        const int mod = 1e9 + 7;\n\n        vector<vector<long long>> g(n, vector<long long>(n, inf));\n        for (auto& e : g) {\n            fill(e.begin(), e.end(), inf);\n        }\n\n        for (auto& r : roads) {\n            int u = r[0], v = r[1], t = r[2];\n            g[u][v] = t;\n            g[v][u] = t;\n        }\n\n        g[0][0] = 0;\n\n        vector<long long> dist(n, inf);\n        fill(dist.begin(), dist.end(), inf);\n        dist[0] = 0;\n\n        vector<long long> f(n);\n        f[0] = 1;\n\n        vector<bool> vis(n);\n        for (int i = 0; i < n; ++i) {\n            int t = -1;\n            for (int j = 0; j < n; ++j) {\n                if (!vis[j] && (t == -1 || dist[j] < dist[t])) {\n                    t = j;\n                }\n            }\n            vis[t] = true;\n            for (int j = 0; j < n; ++j) {\n                if (j == t) {\n                    continue;\n                }\n                long long ne = dist[t] + g[t][j];\n                if (dist[j] > ne) {\n                    dist[j] = ne;\n                    f[j] = f[t];\n                } else if (dist[j] == ne) {\n                    f[j] = (f[j] + f[t]) % mod;\n                }\n            }\n        }\n        return (int) f[n - 1];\n    }\n};"
    }
  ],
