  "minimum-time-to-break-locks-ii": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/minimum-time-to-break-locks-ii.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/minimum-time-to-break-locks-ii.cpp",
      "code": "// Time:  O(n^3)\n// Space: O(n^2)\n\n// hungarian algorithm, weighted bipartite matching\nclass Solution {\npublic:\n    int findMinimumTime(vector<int>& strength) {\n        static const int K = 1;\n        const auto& ceil_divide = [](int a, int b) {\n            return (a + b - 1) / b;\n        };\n    \n        vector<vector<int>> adj(size(strength), vector<int>(size(strength)));\n        for (int i = 0; i < size(strength); ++i) {\n            for (int j = 0; j < size(strength); ++j) {\n                adj[i][j] = ceil_divide(strength[i], 1 + j * K);\n            }\n        }\n        return hungarian(adj).first;\n    }\n\nprivate:\n    // Template modified from:\n    // https://github.com/kth-competitive-programming/kactl/blob/main/content/graph/WeightedMatching.h\n    pair<int, vector<int>> hungarian(const vector<vector<int>> &a) {  // Time: O(n^2 * m), Space: O(n + m)\n        if (a.empty()) return {0, {}};\n        int n = size(a) + 1, m = size(a[0]) + 1;\n        vector<int> u(n), v(m), p(m), ans(n - 1);\n        for (int i = 1; i < n; ++i) {\n            p[0] = i;\n            int j0 = 0; // add \"dummy\" worker 0\n            vector<int> dist(m, numeric_limits<int>::max()), pre(m, -1);\n            vector<bool> done(m + 1);\n            do { // dijkstra\n                done[j0] = true;\n                int i0 = p[j0], j1, delta = numeric_limits<int>::max();\n                for (int j = 1; j < m; ++j) {\n                    if (!done[j]) {\n                        auto cur = a[i0 - 1][j - 1] - u[i0] - v[j];\n                        if (cur < dist[j]) dist[j] = cur, pre[j] = j0;\n                        if (dist[j] < delta) delta = dist[j], j1 = j;\n                    }\n                }\n                for (int j = 0; j < m; ++j) {\n                    if (done[j]) u[p[j]] += delta, v[j] -= delta;\n                    else dist[j] -= delta;\n                }\n                j0 = j1;\n            } while (p[j0]);\n            while (j0) { // update alternating path\n                int j1 = pre[j0];\n                p[j0] = p[j1], j0 = j1;\n            }\n        }\n        for (int j = 1; j < m; ++j) if (p[j]) ans[p[j] - 1] = j - 1;\n        return {-v[0], ans}; // min cost\n    }\n};"
    }
  ],
