      "code": "class Solution {\npublic:\n    int tallestBillboard(vector<int>& rods) {\n        int s = accumulate(rods.begin(), rods.end(), 0);\n        int n = rods.size();\n        int f[n][s + 1];\n        memset(f, -1, sizeof(f));\n        function<int(int, int)> dfs = [&](int i, int j) -> int {\n            if (i >= n) {\n                return j == 0 ? 0 : -(1 << 30);\n            }\n            if (f[i][j] != -1) {\n                return f[i][j];\n            }\n            int ans = max(dfs(i + 1, j), dfs(i + 1, j + rods[i]));\n            ans = max(ans, dfs(i + 1, abs(j - rods[i])) + min(j, rods[i]));\n            return f[i][j] = ans;\n        };\n        return dfs(0, 0);\n    }\n};"
