      "code": "class Solution {\npublic:\n    int minScoreTriangulation(vector<int>& values) {\n        int n = values.size();\n        vector<vector<int>> f(n, vector<int>(n));\n        auto dfs = [&](this auto&& dfs, int i, int j) -> int {\n            if (i + 1 == j) {\n                return 0;\n            }\n            if (f[i][j]) {\n                return f[i][j];\n            }\n            int ans = 1 << 30;\n            for (int k = i + 1; k < j; ++k) {\n                ans = min(ans, dfs(i, k) + dfs(k, j) + values[i] * values[k] * values[j]);\n            }\n            return f[i][j] = ans;\n        };\n        return dfs(0, n - 1);\n    }\n};"
