  "find-maximum-non-decreasing-array-length": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 2945.Find Maximum Non-decreasing Array Length Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/2900-2999/2945.Find%20Maximum%20Non-decreasing%20Array%20Length/README.md",
      "code": "class Solution {\npublic:\n    int findMaximumLength(vector<int>& nums) {\n        int n = nums.size();\n        int f[n + 1];\n        int pre[n + 2];\n        long long s[n + 1];\n        for (int i = 0; i < n; ++i) {\n            s[i + 1] = s[i] + nums[i];\n        }\n        memset(f, 0, sizeof(f));\n        memset(pre, 0, sizeof(pre));\n        for (int i = 1; i <= n; ++i) {\n            pre[i] = max(pre[i], pre[i - 1]);\n            f[i] = f[pre[i]] + 1;\n            int j = lower_bound(s, s + n + 1, s[i] * 2 - s[pre[i]]) - s;\n            pre[j] = i;\n        }\n        return f[n];\n    }\n};"
    }
  ],
