      "code": "class Solution {\npublic:\n    int numSplits(string s) {\n        unordered_map<char, int> cnt;\n        for (char& c : s) {\n            ++cnt[c];\n        }\n        unordered_set<char> vis;\n        int ans = 0;\n        for (char& c : s) {\n            vis.insert(c);\n            if (--cnt[c] == 0) {\n                cnt.erase(c);\n            }\n            ans += vis.size() == cnt.size();\n        }\n        return ans;\n    }\n};"
