  "minimum-cost-to-move-between-indices": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3919.Minimum Cost to Move Between Indices Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3900-3999/3919.Minimum%20Cost%20to%20Move%20Between%20Indices/README.md",
      "code": "class Solution {\npublic:\n    vector<int> minCost(vector<int>& nums, vector<vector<int>>& queries) {\n        int n = nums.size();\n        vector<int> s1(n, 0);\n        vector<int> s2(n, 0);\n        for (int i = 1; i < n; i++) {\n            int c1 = (i > 1 && nums[i - 1] - nums[i - 2] <= nums[i] - nums[i - 1]) ? nums[i] - nums[i - 1] : 1;\n            int c2 = (i < n - 1 && nums[i] - nums[i - 1] > nums[i + 1] - nums[i]) ? nums[i] - nums[i - 1] : 1;\n            s1[i] = s1[i - 1] + c1;\n            s2[i] = s2[i - 1] + c2;\n        }\n        int m = queries.size();\n        vector<int> ans(m);\n        for (int i = 0; i < m; i++) {\n            int l = queries[i][0];\n            int r = queries[i][1];\n            ans[i] = (l < r) ? s1[r] - s1[l] : s2[l] - s2[r];\n        }\n        return ans;\n    }\n};"
    }
  ],
  "largest-magic-square": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(m \\times n \\times \\min(m, n)^2)$，空间复杂度 $O(m \\times n)$ / Space $O(m \\times n)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 1895.Largest Magic Square Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/1800-1899/1895.Largest%20Magic%20Square/README.md",
      "code": "class Solution {\npublic:\n    vector<vector<int>> rowsum;\n    vector<vector<int>> colsum;\n\n    int largestMagicSquare(vector<vector<int>>& grid) {\n        int m = grid.size(), n = grid[0].size();\n        rowsum.assign(m + 1, vector<int>(n + 1, 0));\n        colsum.assign(m + 1, vector<int>(n + 1, 0));\n        for (int i = 1; i <= m; ++i) {\n            for (int j = 1; j <= n; ++j) {\n                rowsum[i][j] = rowsum[i][j - 1] + grid[i - 1][j - 1];\n                colsum[i][j] = colsum[i - 1][j] + grid[i - 1][j - 1];\n            }\n        }\n        for (int k = min(m, n); k > 1; --k) {\n            for (int i = 0; i + k - 1 < m; ++i) {\n                for (int j = 0; j + k - 1 < n; ++j) {\n                    int i2 = i + k - 1, j2 = j + k - 1;\n                    if (check(grid, i, j, i2, j2)) {\n                        return k;\n                    }\n                }\n            }\n        }\n        return 1;\n    }\n\n    bool check(vector<vector<int>>& grid, int x1, int y1, int x2, int y2) {\n        int val = rowsum[x1 + 1][y2 + 1] - rowsum[x1 + 1][y1];\n        for (int i = x1 + 1; i <= x2; ++i) {\n            if (rowsum[i + 1][y2 + 1] - rowsum[i + 1][y1] != val) {\n                return false;\n            }\n        }\n        for (int j = y1; j <= y2; ++j) {\n            if (colsum[x2 + 1][j + 1] - colsum[x1][j + 1] != val) {\n                return false;\n            }\n        }\n        int s = 0;\n        for (int i = x1, j = y1; i <= x2; ++i, ++j) {\n            s += grid[i][j];\n        }\n        if (s != val) {\n            return false;\n        }\n        s = 0;\n        for (int i = x1, j = y2; i <= x2; ++i, --j) {\n            s += grid[i][j];\n        }\n        if (s != val) {\n            return false;\n        }\n        return true;\n    }\n};"
    }
  ],
  "plates-between-candles": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 2055.Plates Between Candles Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/2000-2099/2055.Plates%20Between%20Candles/README.md",
      "code": "class Solution {\npublic:\n    vector<int> platesBetweenCandles(string s, vector<vector<int>>& queries) {\n        int n = s.size();\n        vector<int> presum(n + 1);\n        for (int i = 0; i < n; ++i) presum[i + 1] = presum[i] + (s[i] == '*');\n        vector<int> left(n);\n        vector<int> right(n);\n        for (int i = 0, l = -1; i < n; ++i) {\n            if (s[i] == '|') l = i;\n            left[i] = l;\n        }\n        for (int i = n - 1, r = -1; i >= 0; --i) {\n            if (s[i] == '|') r = i;\n            right[i] = r;\n        }\n        vector<int> ans(queries.size());\n        for (int k = 0; k < queries.size(); ++k) {\n            int i = right[queries[k][0]];\n            int j = left[queries[k][1]];\n            if (i >= 0 && j >= 0 && i < j) ans[k] = presum[j] - presum[i + 1];\n        }\n        return ans;\n    }\n};"
    }
  ],
