  "count-subarrays-with-cost-less-than-or-equal-to-k": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n)$，空间复杂度 $O(n)$ / Space $O(n)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3835.Count Subarrays With Cost Less Than or Equal to K Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3800-3899/3835.Count%20Subarrays%20With%20Cost%20Less%20Than%20or%20Equal%20to%20K/README.md",
      "code": "class Solution {\npublic:\n    long long countSubarrays(vector<int>& nums, long long k) {\n        long long ans = 0;\n        deque<int> q1, q2;\n        int l = 0;\n\n        for (int r = 0; r < nums.size(); r++) {\n            int x = nums[r];\n\n            while (!q1.empty() && nums[q1.back()] <= x) {\n                q1.pop_back();\n            }\n            while (!q2.empty() && nums[q2.back()] >= x) {\n                q2.pop_back();\n            }\n            q1.push_back(r);\n            q2.push_back(r);\n\n            while (l < r && (long long) (nums[q1.front()] - nums[q2.front()]) * (r - l + 1) > k) {\n                l++;\n                if (q1.front() < l) {\n                    q1.pop_front();\n                }\n                if (q2.front() < l) {\n                    q2.pop_front();\n                }\n            }\n\n            ans += r - l + 1;\n        }\n        return ans;\n    }\n};"
    }
  ],
  "maximum-number-of-robots-within-budget": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n)$，空间复杂度 $O(n)$，其中 $n$ 是题目中机器人的数目 / Space $O(n)$，其中 $n$ 是题目中机器人的数目",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 2398.Maximum Number of Robots Within Budget Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/2300-2399/2398.Maximum%20Number%20of%20Robots%20Within%20Budget/README.md",
      "code": "class Solution {\npublic:\n    int maximumRobots(vector<int>& chargeTimes, vector<int>& runningCosts, long long budget) {\n        deque<int> q;\n        long long s = 0;\n        int ans = 0;\n        int n = chargeTimes.size();\n        for (int l = 0, r = 0; r < n; ++r) {\n            s += runningCosts[r];\n            while (q.size() && chargeTimes[q.back()] <= chargeTimes[r]) {\n                q.pop_back();\n            }\n            q.push_back(r);\n            while (q.size() && (r - l + 1) * s + chargeTimes[q.front()] > budget) {\n                if (q.front() == l) {\n                    q.pop_front();\n                }\n                s -= runningCosts[l++];\n            }\n            ans = max(ans, r - l + 1);\n        }\n        return ans;\n    }\n};"
    }
  ],
  "count-prime-gap-balanced-subarrays": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/count-prime-gap-balanced-subarrays.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/count-prime-gap-balanced-subarrays.cpp",
      "code": "// Time:  precompute: O(r), r = max(nums)\n//        runtime:    O(n)\n// Space: O(r)\n\n// number theory, mono deque, two pointers, sliding window\nvector<int> linear_sieve_of_eratosthenes(int n) {  // Time: O(n), Space: O(n)\n    vector<int> spf(n + 1, -1);\n    vector<int> primes;\n    for (int i = 2; i <= n; ++i) {\n        if (spf[i] == -1) {\n            spf[i] = i;\n            primes.emplace_back(i);\n        }\n        for (const auto& p : primes) {\n            if (i * p > n || p > spf[i]) {\n                break;\n            }\n            spf[i * p] = p;\n        }\n    }\n    return spf;\n};\n\nconst int MAX_NUMS = 5 * 1e4;\nconst auto& SPF = linear_sieve_of_eratosthenes(MAX_NUMS);\nclass Solution {\npublic:\n    int primeSubarray(vector<int>& nums, int k) {\n        deque<int> idxs, max_dq, min_dq;\n        int result = 0;\n        for (int right = 0, left = 0; right < size(nums); ++right) {\n            if (SPF[nums[right]] == nums[right]) {\n                idxs.emplace_back(right);\n                while (!empty(max_dq) && nums[max_dq.back()] <= nums[right]) {\n                    max_dq.pop_back();\n                }\n                max_dq.emplace_back(right);\n                while (!empty(min_dq) && nums[min_dq.back()] >= nums[right]) {\n                    min_dq.pop_back();\n                }\n                min_dq.emplace_back(right);\n                for (; nums[max_dq[0]] - nums[min_dq[0]] > k; ++left) {\n                    if (max_dq[0] == left) {\n                        max_dq.pop_front();\n                    }\n                    if (min_dq[0] == left) {\n                        min_dq.pop_front();\n                    }\n                    if (idxs[0] == left) {\n                        idxs.pop_front();\n                    }\n                }\n            }\n            if (size(idxs) >= 2) {\n                result += (idxs[size(idxs) - 2]) - left + 1;\n            }\n        }\n        return result;\n    }\n};"
    }
  ],
