      "code": "class Solution {\npublic:\n    long long minEliminationTime(vector<int>& timeReq, int splitTime) {\n        using ll = long long;\n        priority_queue<ll, vector<ll>, greater<ll>> pq;\n        for (int v : timeReq) {\n            pq.push(v);\n        }\n        while (pq.size() > 1) {\n            pq.pop();\n            ll x = pq.top();\n            pq.pop();\n            pq.push(x + splitTime);\n        }\n        return pq.top();\n    }\n};"
