      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n \\times m)$，空间复杂度 $O(n \\times m)$ / Space $O(n \\times m)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
