      "code": "class Solution {\npublic:\n    bool checkPrimeFrequency(vector<int>& nums) {\n        unordered_map<int, int> cnt;\n        for (int x : nums) {\n            ++cnt[x];\n        }\n\n        for (auto& [_, x] : cnt) {\n            if (isPrime(x)) {\n                return true;\n            }\n        }\n        return false;\n    }\n\nprivate:\n    bool isPrime(int x) {\n        if (x < 2) {\n            return false;\n        }\n        for (int i = 2; i <= x / i; ++i) {\n            if (x % i == 0) {\n                return false;\n            }\n        }\n        return true;\n    }\n};"
