  "check-if-digits-are-equal-in-string-after-operations-ii": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/check-if-digits-are-equal-in-string-after-operations-ii.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/check-if-digits-are-equal-in-string-after-operations-ii.cpp",
      "code": "// Time:  O(nlogn)\n// Space: O(1)\n\n// fast exponentiation\nclass Solution {\npublic:\n    bool hasSameDigits(string s) {\n        const auto& pow = [](uint64_t a, int b, int m) {  // O(logMOD) = O(1)\n            a %= m;\n            uint64_t result = 1;\n            while (b) {\n                if (b & 1) {\n                    result = (result * a) % m;\n                }\n                a = (a * a) % m;\n                b >>= 1;\n            }\n            return result;\n        };\n\n        const auto& check = [&](int mod) {\n            const auto& decompose = [](int x, int mod) {  // x = a * mod^cnt\n                int cnt = 0;\n                while (x > 1 && x % mod == 0) {\n                    x /= mod;\n                    ++cnt;\n                }\n                return pair(x, cnt);\n            };\n\n            int result = 0, cnt = 0;\n            int curr = 1;\n            for (int i = 0; i <= size(s) - 2; ++i) {\n                if (cnt == 0) {\n                    result = (result + curr * (s[i] - s[i + 1])) % mod;\n                }\n                const auto& [x1, c1] = decompose(size(s) - 2 - i, mod);\n                curr = (curr * x1) % mod;\n                cnt += c1;\n                const auto& [x2, c2] = decompose(i + 1, mod);\n                curr = (curr * pow(x2, mod - 2, mod)) % mod;\n                cnt -= c2;\n            }\n            return result == 0;\n        };\n\n        return check(2) && check(5);\n    }\n};\n\n// Time:  O(nlogn)\n// Space: O(1)\nvector<vector<int>> LOOKUP(5 + 1, vector<int>(5 + 1, -1));\n\n// lucas's theorem\nclass Solution2 {\npublic:\n    bool hasSameDigits(string s) {\n        const auto& nCr = [&](int n, int r) {\n            if (n - r < r) {\n                r = n - r;\n            }\n            if (LOOKUP[n][r] == -1) {\n                int c = 1;\n                for (int k = 1; k <= r; ++k) {\n                    c *= n - k + 1;\n                    c /= k;\n                }\n                LOOKUP[n][r] = c;\n            }\n            return LOOKUP[n][r];\n        };\n\n        // https://en.wikipedia.org/wiki/Lucas%27s_theorem\n        const auto& nCr_mod = [&](int n, int r, int mod) {\n            int result = 1;\n            while (n > 0 || r > 0) {\n                const int ni = n % mod;\n                n /= mod;\n                const int ri = r % mod;\n                r /= mod;\n                if (ni < ri) {\n                    return 0;\n                }\n                result = (result * nCr(ni, ri)) % mod;\n            }\n            return result;\n        };\n\n        vector<vector<int>> lookup(2, vector<int>(5));\n        for (int i = 0; i < 10; ++i) {\n            lookup[i % 2][i % 5] = i;\n        }\n        const auto& nC10 = [&](int n, int k) {\n            return lookup[nCr_mod(n, k, 2)][nCr_mod(n, k, 5)];\n        };\n\n        int total = 0;\n        for (int i = 0; i <= size(s) - 2; ++i) {\n            total = (total + nC10(size(s) - 2, i) * (((s[i] - s[i + 1]) % 10 + 10) % 10)) % 10;\n        }\n        return total == 0;\n    }\n};"
    }
  ],
  "number-of-ways-to-reorder-array-to-get-same-bst": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(n^2)$，空间复杂度 $O(n^2)$ / Space $O(n^2)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 1569.Number of Ways to Reorder Array to Get Same BST Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/1500-1599/1569.Number%20of%20Ways%20to%20Reorder%20Array%20to%20Get%20Same%20BST/README.md",
      "code": "class Solution {\npublic:\n    int numOfWays(vector<int>& nums) {\n        int n = nums.size();\n        const int mod = 1e9 + 7;\n        int c[n][n];\n        memset(c, 0, sizeof(c));\n        c[0][0] = 1;\n        for (int i = 1; i < n; ++i) {\n            c[i][0] = 1;\n            for (int j = 1; j <= i; ++j) {\n                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;\n            }\n        }\n        function<int(vector<int>)> dfs = [&](vector<int> nums) -> int {\n            if (nums.size() < 2) {\n                return 1;\n            }\n            vector<int> left, right;\n            for (int& x : nums) {\n                if (x < nums[0]) {\n                    left.push_back(x);\n                } else if (x > nums[0]) {\n                    right.push_back(x);\n                }\n            }\n            int m = left.size(), n = right.size();\n            int a = dfs(left), b = dfs(right);\n            return c[m + n][m] * 1ll * a % mod * b % mod;\n        };\n        return (dfs(nums) - 1 + mod) % mod;\n    }\n};"
    }
  ],
