  "minimum-swaps-to-avoid-forbidden-values": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/minimum-swaps-to-avoid-forbidden-values.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/minimum-swaps-to-avoid-forbidden-values.cpp",
      "code": "// Time:  O(n)\n// Space: O(1)\n\n// boyer-moore majority vote algorithm, greedy\nclass Solution {\npublic:\n    int minSwaps(vector<int>& nums, vector<int>& forbidden) {\n        const auto& boyer_moore_majority_vote = [&]() {\n            int result = 0, cnt = 0;\n            for (int i = 0; i < size(nums); ++i) {\n                if (nums[i] != forbidden[i]) {\n                    continue;\n                }\n                if (cnt == 0) {\n                    result = nums[i];\n                }\n                if (nums[i] == result) {\n                    ++cnt;\n                } else {\n                    --cnt;\n                }\n            }\n            return result; \n        };\n\n        const auto& m = boyer_moore_majority_vote();\n        int cnt = 0, cnt_m = 0, bal = 0;\n        for (int i = 0; i < size(nums); ++i) {\n            if (nums[i] != forbidden[i]) {\n                if (nums[i] != m  && m != forbidden[i]) {\n                    ++bal;\n                }\n                continue;\n            }\n            ++cnt;\n            if (nums[i] != m) {\n                ++bal;\n            } else {\n                --bal;\n                ++cnt_m;\n            }\n        }\n        return bal >= 0 ? max(cnt_m, (cnt + 1) / 2) : -1;\n    }\n};\n\n// Time:  O(n)\n// Space: O(n)\n// freq table, greedy\nclass Solution2 {\npublic:\n    int minSwaps(vector<int>& nums, vector<int>& forbidden) {\n        unordered_map<int, int> cnt1;\n        for (const auto& x : nums) {\n            ++cnt1[x];\n        }\n        unordered_map<int, int> cnt2;\n        for (const auto& x : forbidden) {\n            ++cnt2[x];\n        }\n        if (any_of(cbegin(cnt1), cend(cnt1), [&](const auto& x) {\n            return x.second +cnt2[x.first] > size(nums);\n        })) {\n            return -1;\n        }\n        unordered_map<int, int> cnt3;\n        int cnt = 0, cnt_m = 0;\n        for (int i = 0; i < size(nums); ++i) {\n            if (nums[i] != forbidden[i]) {\n                continue;\n            }\n            ++cnt;\n            cnt_m = max(cnt_m, ++cnt3[nums[i]]);\n        }\n        return max(cnt_m, (cnt + 1) / 2);\n    }\n};"
    }
  ],
  "two-letter-card-game": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/two-letter-card-game.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/two-letter-card-game.cpp",
      "code": "// Time:  O(n + 26)\n// Space: O(26)\n\n// freq table, math\nclass Solution {\npublic:\n    int score(vector<string>& cards, char x) {\n        vector<int> cnt1(10), cnt2(10);\n        int cnt3 = 0;\n        for (const auto& s : cards) {\n            if (s.find(x) == string::npos) {\n                continue;\n            }\n            if (s[0] == x && s[1] == x) {\n                ++cnt3;\n            } else if (s[0] == x) {\n                ++cnt1[s[1] - 'a'];\n            } else if (s[1] == x) {\n                ++cnt2[s[0] - 'a'];\n            }\n        }\n        const int total1 = accumulate(cbegin(cnt1), cend(cnt1), 0);\n        const int total2 = accumulate(cbegin(cnt2), cend(cnt2), 0);\n        const int mx1 = ranges::max(cnt1);\n        const int mx2 = ranges::max(cnt2);\n        const int pair1 = min(total1 - mx1, total1 / 2);\n        const int pair2 = min(total2 - mx2, total2 / 2);\n        const int pair3 = min((total1 - 2 * pair1) + (total2 - 2 * pair2), cnt3);\n        return (pair1 + pair2) + pair3 + min(pair1 + pair2, (cnt3 - pair3) / 2);\n    }\n};"
    }
  ],
  "minimum-operations-to-make-array-elements-zero": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(q \\log M)$，其中 $q$ 是查询次数，而 $M$ 是查询范围的最大值 / Space $O(1)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3495.Minimum Operations to Make Array Elements Zero Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3400-3499/3495.Minimum%20Operations%20to%20Make%20Array%20Elements%20Zero/README.md",
      "code": "class Solution {\npublic:\n    long long minOperations(vector<vector<int>>& queries) {\n        auto f = [&](long long x) {\n            long long res = 0;\n            long long p = 1;\n            int i = 1;\n            while (p <= x) {\n                long long cnt = min(p * 4 - 1, x) - p + 1;\n                res += cnt * i;\n                i++;\n                p *= 4;\n            }\n            return res;\n        };\n\n        long long ans = 0;\n        for (auto& q : queries) {\n            int l = q[0], r = q[1];\n            long long s = f(r) - f(l - 1);\n            long long mx = f(r) - f(r - 1);\n            ans += max((s + 1) / 2, mx);\n        }\n        return ans;\n    }\n};"
    }
  ],
  "minimum-cost-to-equalize-array": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/minimum-cost-to-equalize-array.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/minimum-cost-to-equalize-array.cpp",
      "code": "// Time:  O(n)\n// Space: O(1)\n\n// constructive algorithms, math\nclass Solution {\npublic:\n    int minCostToEqualizeArray(vector<int>& nums, int cost1, int cost2) {\n        static const int MOD = 1e9 + 7;\n\n        const int n = size(nums);\n        const int64_t mx = ranges::max(nums);\n        int64_t total = mx * n - accumulate(cbegin(nums), cend(nums), 0ll);\n        // fill until mx with only cost1 operations\n        if (n <= 2 || 2 * cost1 <= cost2) {\n            return total * cost1 % MOD;\n        }\n\n        int64_t result = numeric_limits<int64_t>::max();\n        // fill until mx with more cost2 operations and fewer cost1 operations\n        const int64_t mn = ranges::min(nums);\n        int64_t cnt1 = max((mx - mn) - (total - (mx - mn)), static_cast<int64_t>(0));\n        int64_t cnt2 = total - cnt1;\n        result = min(result, (cnt1 + cnt2 % 2) * cost1 + cnt2 / 2 * cost2);\n\n        // fill until mx+x with most cost2 operations and fewest cost1 operations,\n        // where x is the max of x s.t. cnt1+x >= (n-1)*x => cnt1 >= (n-2)*x\n        const int64_t x = cnt1 / (n - 2);\n        cnt1 %= n - 2;\n        total += n * x;\n        cnt2 = total - cnt1;\n        result = min(result, (cnt1 + cnt2 % 2) * cost1 + (cnt2 / 2) * cost2);\n\n        // fill until mx+x+1 or mx+x+2 with nearly all cost2 operations and at most one cost1 operation\n        for (int _ = 0; _ < 2; ++_) {  // increase twice is for odd n\n            total += n;\n            result = min(result, total % 2 * cost1 + total / 2 * cost2);\n        }\n        return result % MOD;\n    }\n};"
    }
  ],
