  "select-k-disjoint-special-substrings": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/select-k-disjoint-special-substrings.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/select-k-disjoint-special-substrings.cpp",
      "code": "// Time:  O(n + 26^3)\n// Space: O(26)\n\n// hash table, sort, greedy\nclass Solution {\npublic:\n    bool maxSubstringLength(string s, int k) {\n        const auto& erase_overlap_intervals = [](auto& intervals) {\n            sort(begin(intervals), end(intervals), [](const auto& a, const auto& b) { return a[1] < b[1]; });\n            int result = 0, right = numeric_limits<int>::min();\n            for (const auto& x : intervals) {\n                if (x[0] <= right) {\n                    ++result;\n                } else {\n                    right = x[1];\n                }\n            }\n            return result;\n        };\n\n        vector<int> cnt(26), lookup1(26, -1), lookup2(26, -1);\n        for (int i = 0; i < size(s); ++i) {\n            ++cnt[s[i] - 'a'];\n            if (lookup1[s[i] - 'a'] == -1) {\n                lookup1[s[i] - 'a'] = i;\n            }\n            lookup2[s[i] - 'a'] = i;\n        }\n        vector<vector<int>> intervals;\n        for (const auto& i : lookup1) {\n            if (i == -1) {\n                continue;\n            }\n            for (const auto& j : lookup2) {\n                if (j == -1 || i > j) {\n                    continue;\n                }\n                int total = 0;\n                for (int c = 0; c < size(cnt); ++c) {\n                    if (i <= lookup1[c] && lookup1[c] <= lookup2[c] && lookup2[c] <= j) {\n                        total += cnt[c];\n                    }\n                }\n                if (total == j - i + 1 && total < size(s)) {\n                    intervals.emplace_back(vector<int>{i, j});\n                }\n            }\n        }\n        return size(intervals) - erase_overlap_intervals(intervals) >= k;\n    }\n};\n\n// Time:  O(26 * n + 26 * log(26))\n// Space: O(26)\n// hash table, sort, greedy\nclass Solution2 {\npublic:\n    bool maxSubstringLength(string s, int k) {\n        const auto& erase_overlap_intervals = [](auto& intervals) {\n            sort(begin(intervals), end(intervals), [](const auto& a, const auto& b) { return a[1] < b[1]; });\n            int result = 0, right = numeric_limits<int>::min();\n            for (const auto& x : intervals) {\n                if (x[0] <= right) {\n                    ++result;\n                } else {\n                    right = x[1];\n                }\n            }\n            return result;\n        };\n\n        vector<char> cnt(26);\n        vector<int> lookup1(26, -1), lookup2(26, -1);\n        for (int i = 0; i < size(s); ++i) {\n            ++cnt[s[i] - 'a'];\n            if (lookup1[s[i] - 'a'] == -1) {\n                lookup1[s[i] - 'a'] = i;\n            }\n            lookup2[s[i] - 'a'] = i;\n        }\n        vector<vector<int>> intervals;\n        for (int i = 0; i < size(s); ++i) {\n            if (i != lookup1[s[i] - 'a']) {\n                continue;\n            }\n            int x = i + 1, j = lookup2[s[i] - 'a'];\n            for (; x <= j && lookup1[s[x] - 'a'] >= i; ++x) {\n                j = max(j, lookup2[s[x] - 'a']);\n            }\n            if (x == j + 1 && (i != 0 || j != size(s) - 1)) {\n                intervals.emplace_back(vector<int>{i, j});\n            }\n        }\n        return size(intervals) - erase_overlap_intervals(intervals) >= k;\n    }\n};"
    }
  ],
