  "maximum-sum-of-edge-values-in-a-graph": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Modern C++ reference",
      "complexity": null,
      "license": "MIT",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "kamyu104 C++/maximum-sum-of-edge-values-in-a-graph.cpp",
      "sourceUrl": "https://github.com/kamyu104/LeetCode-Solutions/blob/master/C%2B%2B/maximum-sum-of-edge-values-in-a-graph.cpp",
      "code": "// Time:  O(n)\n// Space: O(n)\n\n// flood fill, bfs, counting sort, greedy\n/* \nn = 11\nedges = [[0,1],[1,2],[2,3],[5,6],[6,7]]\nmax is 367 but ans is 366, which is wrong by greedy\n*/\nclass Solution_WA {\npublic:\n    long long maxScore(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> adj(n);\n        for (const auto& e : edges) {\n            adj[e[0]].emplace_back(e[1]);\n            adj[e[1]].emplace_back(e[0]);\n        }\n        vector<bool> lookup(n);\n        const auto& bfs = [&](int u) {\n            lookup[u] = true;\n            vector<int> result = {u};\n            for (int i = 0; i < size(result); ++i){\n                const auto& u = result[i];\n                for (const auto& v : adj[u]) {\n                    if (lookup[v]) {\n                        continue;\n                    }\n                    lookup[v] = true;\n                    result.emplace_back(v);\n                }\n            }\n            return result;\n        };\n\n        const auto& f = [](int l, int r, bool is_cycle) {\n            int64_t a = r, b = r;\n            int64_t result = 0;\n            for (int64_t c = r - 1; c >= l; --c) {\n                result += a * c;\n                tie(a, b) = pair(b, c);\n            }\n            if (is_cycle) {\n                result += a * b;\n            }\n            return result;\n        };\n\n        vector<int> chains, cycles;\n        for (int u = 0; u < n; ++u) {\n            if (lookup[u]) {\n                continue;\n            }\n            const auto& comp = bfs(u);\n            if (all_of(cbegin(comp), cend(comp), [&](const auto& x) {\n                return size(adj[x]) == 2;\n            })) {\n                cycles.emplace_back(size(comp));\n            } else {\n                chains.emplace_back(size(comp));\n            }\n        }\n        int64_t result = 0;\n        for (const auto& l : cycles) {\n            result += f(n - l + 1, n, true);\n            n -= l;\n        }\n        const int max_chain = empty(chains) ? 0 : ranges::max(chains);\n        vector<int> cnt(max_chain + 1);\n        for (const auto& l: chains) {\n            ++cnt[l];\n        }\n        for (int l = size(cnt) - 1; l >= 0; --l) {\n            for (int _ = 0; _ < cnt[l]; ++_) {\n                result += f(n - l + 1, n, false);\n                n -= l;\n            }\n        }\n        return result;\n    }\n};"
    }
  ],
  "minimum-non-zero-product-of-the-array-elements": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": "Time $O(p)$，空间复杂度 $O(1)$ / Space $O(1)$",
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 1969.Minimum Non-Zero Product of the Array Elements Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/1900-1999/1969.Minimum%20Non-Zero%20Product%20of%20the%20Array%20Elements/README.md",
      "code": "class Solution {\npublic:\n    int minNonZeroProduct(int p) {\n        using ll = long long;\n        const int mod = 1e9 + 7;\n        auto qpow = [](ll a, ll n) {\n            ll ans = 1;\n            for (; n; n >>= 1) {\n                if (n & 1) {\n                    ans = ans * a % mod;\n                }\n                a = a * a % mod;\n            }\n            return ans;\n        };\n        ll a = ((1LL << p) - 1) % mod;\n        ll b = qpow(((1LL << p) - 2) % mod, (1L << (p - 1)) - 1);\n        return a * b % mod;\n    }\n};"
    }
  ],
