      "code": "/**\n * Definition for a binary tree node.\n * struct TreeNode {\n *     int val;\n *     TreeNode *left;\n *     TreeNode *right;\n *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}\n * };\n */\nclass Solution {\npublic:\n    unordered_set<int> s;\n\n    int numColor(TreeNode* root) {\n        dfs(root);\n        return s.size();\n    }\n\n    void dfs(TreeNode* root) {\n        if (!root) return;\n        s.insert(root->val);\n        dfs(root->left);\n        dfs(root->right);\n    }\n};"
