      "code": "class Solution {\npublic:\n    bool differByOne(vector<string>& dict) {\n        unordered_set<string> s;\n        for (auto word : dict) {\n            for (int i = 0; i < word.size(); ++i) {\n                auto t = word;\n                t[i] = '*';\n                if (s.count(t)) return true;\n                s.insert(t);\n            }\n        }\n        return false;\n    }\n};"
