  "longest-common-prefix-of-k-strings-after-removal": [
    {
      "language": "C++",
      "status": "Reference",
      "provenance": "external-reference",
      "approachTitle": "Reference",
      "complexity": null,
      "license": "CC-BY-SA-4.0",
      "modified": false,
      "submittedAt": null,
      "runtime": null,
      "memory": null,
      "sourceTitle": "Doocs 3485.Longest Common Prefix of K Strings After Removal Reference",
      "sourceUrl": "https://github.com/doocs/leetcode/blob/main/solution/3400-3499/3485.Longest%20Common%20Prefix%20of%20K%20Strings%20After%20Removal/README.md",
      "code": "class Solution {\npublic:\n    struct TrieNode {\n        int count = 0;\n        int depth = 0;\n        int children[26] = {0};\n    };\n\n    class SegmentTree {\n    public:\n        int n;\n        vector<int> tree;\n        vector<int>& globalCount;\n        SegmentTree(int n, vector<int>& globalCount)\n            : n(n)\n            , globalCount(globalCount) {\n            tree.assign(4 * (n + 1), -1);\n            build(1, 1, n);\n        }\n        void build(int idx, int l, int r) {\n            if (l == r) {\n                tree[idx] = globalCount[l] > 0 ? l : -1;\n                return;\n            }\n            int mid = (l + r) / 2;\n            build(idx * 2, l, mid);\n            build(idx * 2 + 1, mid + 1, r);\n            tree[idx] = max(tree[idx * 2], tree[idx * 2 + 1]);\n        }\n        void update(int idx, int l, int r, int pos, int newVal) {\n            if (l == r) {\n                tree[idx] = newVal > 0 ? l : -1;\n                return;\n            }\n            int mid = (l + r) / 2;\n            if (pos <= mid)\n                update(idx * 2, l, mid, pos, newVal);\n            else\n                update(idx * 2 + 1, mid + 1, r, pos, newVal);\n            tree[idx] = max(tree[idx * 2], tree[idx * 2 + 1]);\n        }\n        int query() {\n            return tree[1];\n        }\n    };\n\n    vector<int> longestCommonPrefix(vector<string>& words, int k) {\n        int n = words.size();\n        vector<int> ans(n, 0);\n        if (n - 1 < k) return ans;\n        vector<TrieNode> trie(1);\n        for (const string& word : words) {\n            int cur = 0;\n            for (char c : word) {\n                int idx = c - 'a';\n                if (trie[cur].children[idx] == 0) {\n                    trie[cur].children[idx] = trie.size();\n                    trie.push_back({0, trie[cur].depth + 1});\n                }\n                cur = trie[cur].children[idx];\n                trie[cur].count++;\n            }\n        }\n        int maxDepth = 0;\n        for (int i = 1; i < trie.size(); ++i) {\n            if (trie[i].count >= k) {\n                maxDepth = max(maxDepth, trie[i].depth);\n            }\n        }\n        vector<int> globalCount(maxDepth + 1, 0);\n        for (int i = 1; i < trie.size(); ++i) {\n            if (trie[i].count >= k && trie[i].depth <= maxDepth) {\n                globalCount[trie[i].depth]++;\n            }\n        }\n        vector<vector<int>> fragileList(n);\n        for (int i = 0; i < n; ++i) {\n            int cur = 0;\n            for (char c : words[i]) {\n                int idx = c - 'a';\n                cur = trie[cur].children[idx];\n                if (trie[cur].count == k) {\n                    fragileList[i].push_back(trie[cur].depth);\n                }\n            }\n        }\n        int segSize = maxDepth;\n        if (segSize >= 1) {\n            SegmentTree segTree(segSize, globalCount);\n            for (int i = 0; i < n; ++i) {\n                if (n - 1 < k) {\n                    ans[i] = 0;\n                } else {\n                    for (int d : fragileList[i]) {\n                        segTree.update(1, 1, segSize, d, globalCount[d] - 1);\n                    }\n                    int res = segTree.query();\n                    ans[i] = res == -1 ? 0 : res;\n                    for (int d : fragileList[i]) {\n                        segTree.update(1, 1, segSize, d, globalCount[d]);\n                    }\n                }\n            }\n        }\n        return ans;\n    }\n};"
    }
  ],
